package imobiliaria;

import java.sql.SQLException;
import java.text.NumberFormat;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.*;
import java.util.function.Function;

final class View {
    private static final Locale BR=Locale.forLanguageTag("pt-BR");
    private static final DateTimeFormatter DATA=DateTimeFormatter.ofPattern("dd/MM/yyyy 'às' HH:mm");
    private final String csrf;
    private final DTO.Identidade conta;
    private final boolean staff;

    View(String csrf,DTO.Identidade conta,boolean staff){this.csrf=csrf;this.conta=conta;this.staff=staff;}

    static String e(Object valor){return valor==null?"—":valor.toString().replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&#39;");}
    private static String dinheiro(Object valor){return valor==null?"—":NumberFormat.getCurrencyInstance(BR).format(valor);}
    private static String data(Object valor){return valor instanceof LocalDateTime d?d.format(DATA):e(valor);}
    private static String status(Object valor){String t=switch(valor.toString()){case "DISPONIVEL"->"Disponível";case "RESERVADO"->"Reservado";case "VENDIDO"->"Vendido";case "PENDENTE"->"Pendente";case "REALIZADA"->"Realizada";case "CANCELADA"->"Cancelada";default->valor.toString();};return e(t);}
    private static String tipo(String valor){return switch(valor){case "CASA"->"Casa";case "SOBRADO"->"Sobrado";case "APARTAMENTO"->"Apartamento";case "TERRENO"->"Terreno";default->valor;};}

    String pagina(String titulo,String conteudo){
        String nav="<a href='/'>Início</a><a href='/imoveis'>Imóveis</a><a href='/sobre'>Sobre</a><a href='/contato'>Contato</a>";
        if(conta==null)nav+="<a href='/entrar'>Entrar</a><a class='nav-cta' href='/criar-conta'>Criar conta</a>";
        else{nav+="<a href='/perfil'>Meu perfil</a><a href='/visitas'>"+(staff?"Agenda":"Minhas visitas")+"</a>";if(staff)nav+="<a href='/gestao/relatorios'>Gestão</a>";nav+=form("/sair")+"<button class='link'>Sair</button></form>";}
        return """
            <!doctype html><html lang='pt-BR'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width, initial-scale=1'>
            <meta name='description' content='Imóveis selecionados e visitas organizadas em um só lugar'>
            <title>%s · Horizonte Imóveis</title><link rel='stylesheet' href='/estilo.css'></head>
            <body><header><a class='brand' href='/'><span class='brand-mark'>H</span><span>Horizonte<small>IMÓVEIS</small></span></a><nav aria-label='Principal'>%s</nav></header>
            <main>%s</main><footer><div><strong>Horizonte Imóveis</strong><p>Encontre um lugar para chamar de seu.</p></div><div><a href='/imoveis'>Imóveis</a><a href='/sobre'>Sobre</a><a href='/contato'>Contato</a></div><small>Projeto acadêmico · Gustavo de Matos Ximenes</small></footer></body></html>
            """.formatted(e(titulo),nav,conteudo);
    }

    String home(List<DTO.Imovel> imoveis){
        List<DTO.Imovel> destaques=imoveis.stream().filter(DTO.Imovel::destaque).limit(3).toList();
        if(destaques.isEmpty())destaques=imoveis.stream().limit(3).toList();
        String hero="<section class='hero'><div><p class='eyebrow'>IMÓVEIS EM RIO DO SUL</p><h1>Seu próximo endereço começa aqui.</h1><p>Casas selecionadas, informações completas e visitas agendadas com poucos cliques.</p><div class='hero-actions'><a class='button' href='/imoveis'>Explorar imóveis</a><a class='text-link' href='/sobre'>Conheça a imobiliária →</a></div></div><div class='hero-art' aria-hidden='true'><span></span></div></section>";
        String numeros="<section class='numbers'><div><strong>6+</strong><span>imóveis cadastrados</span></div><div><strong>3</strong><span>corretores na equipe</span></div><div><strong>21 dias</strong><span>de horários disponíveis</span></div></section>";
        return pagina("Início",hero+numeros+"<section class='section-head'><div><p class='eyebrow'>DESTAQUES</p><h2>Imóveis que merecem sua visita</h2></div><a href='/imoveis'>Ver todos →</a></section>"+cards(destaques)+"<section class='cta'><div><p class='eyebrow'>AGENDE ONLINE</p><h2>Gostou de um imóvel?</h2><p>Escolha um horário livre e acompanhe tudo pelo seu perfil.</p></div><a class='button light' href='/criar-conta'>Começar agora</a></section>");
    }

    String catalogo(List<DTO.Imovel> imoveis){return pagina("Imóveis","<div class='page-title'><p class='eyebrow'>CATÁLOGO</p><h1>Encontre o imóvel ideal</h1><p>Compare localização, espaço, preço e disponibilidade.</p></div>"+cards(imoveis));}

    private String cards(List<DTO.Imovel> imoveis){
        var b=new StringBuilder("<div class='property-grid'>");int n=0;
        for(var i:imoveis){n++;b.append("<article class='property'><a class='property-photo photo-").append((i.id()%4)+1).append("' href='/imovel?id=").append(i.id()).append("'><span>").append(tipo(i.tipo())).append("</span></a><div class='property-body'><div class='property-meta'><span>").append(e(i.bairro())).append("</span><span class='status'>").append(status(i.status())).append("</span></div><h3><a href='/imovel?id=").append(i.id()).append("'>").append(e(i.titulo())).append("</a></h3><p class='features'>").append(i.quartos()).append(" quartos · ").append(i.banheiros()).append(" banheiros · ").append(e(i.areaM2())).append(" m²</p><strong class='price'>").append(dinheiro(i.preco())).append("</strong></div></article>");}
        return b.append("</div>").toString();
    }

    String detalhe(DTO.Imovel i){
        String acao=i.status()==DTO.StatusImovel.DISPONIVEL?"<a class='button' href='/agendar?imovel="+i.id()+"'>Agendar visita</a>":"<span class='notice'>Este imóvel está "+status(i.status()).toLowerCase(BR)+".</span>";
        return pagina(i.titulo(),"<a class='back' href='/imoveis'>← Voltar aos imóveis</a><section class='detail'><div class='detail-photo photo-"+((i.id()%4)+1)+"'><span>"+tipo(i.tipo())+"</span></div><div class='detail-main'><div class='property-meta'><span>"+e(i.bairro())+", "+e(i.cidade())+"</span><span class='status'>"+status(i.status())+"</span></div><h1>"+e(i.titulo())+"</h1><p class='detail-price'>"+dinheiro(i.preco())+"</p><div class='feature-row'><div><strong>"+i.quartos()+"</strong><span>quartos</span></div><div><strong>"+i.banheiros()+"</strong><span>banheiros</span></div><div><strong>"+i.vagas()+"</strong><span>vagas</span></div><div><strong>"+e(i.areaM2())+"</strong><span>m²</span></div></div>"+acao+"</div></section><section class='description'><div><p class='eyebrow'>SOBRE O IMÓVEL</p><h2>Detalhes da propriedade</h2><p>"+e(i.descricao())+"</p></div><aside><strong>Endereço</strong><p>"+e(i.endereco())+"<br>"+e(i.bairro())+" · "+e(i.cidade())+"</p></aside></section>");
    }

    String sobre(){return pagina("Sobre","<div class='page-title'><p class='eyebrow'>NOSSA HISTÓRIA</p><h1>Imóveis com informação clara e agenda organizada.</h1></div><section class='content-grid'><div><h2>Uma experiência mais simples</h2><p>A Horizonte reúne clientes, proprietários, corretores, imóveis e visitas em um único sistema. Cada casa possui informações completas e horários vinculados à agenda real da equipe.</p></div><div><h2>Decisões orientadas por dados</h2><p>Os relatórios revelam imóveis mais visitados, baixa procura, produtividade dos corretores e os horários de maior movimento.</p></div><div><h2>Tecnologia do projeto</h2><p>Aplicação em Java com HTML e CSS, autenticação do Supabase e dados persistidos no PostgreSQL do Supabase.</p></div></section>");}
    String contato(){return pagina("Contato","<div class='page-title'><p class='eyebrow'>FALE CONOSCO</p><h1>Estamos prontos para ajudar.</h1><p>Use os canais abaixo para tirar dúvidas sobre imóveis e visitas.</p></div><section class='contact-grid'><div><span>TELEFONE</span><strong>(47) 3521-2026</strong><p>Segunda a sexta, das 8h às 18h.</p></div><div><span>E-MAIL</span><strong>contato@horizonte.test</strong><p>Respondemos em até um dia útil.</p></div><div><span>ENDEREÇO</span><strong>Centro · Rio do Sul</strong><p>Atendimento presencial com horário marcado.</p></div></section>");}

    String login(boolean cadastro,boolean confirmar){String titulo=cadastro?"Criar sua conta":"Bem-vindo de volta";String mensagem=confirmar?"<div class='notice ok'>Confira seu e-mail e confirme a conta antes de entrar.</div>":"";String nome=cadastro?input("Nome completo","nome","text",100):"";String alt=cadastro?"<a href='/entrar'>Já tenho uma conta</a>":"<a href='/criar-conta'>Ainda não tenho conta</a>";return pagina(titulo,"<section class='auth-layout'><div><p class='eyebrow'>ÁREA DO CLIENTE</p><h1>"+titulo+"</h1><p>Agende visitas, acompanhe seu histórico e atualize seus dados.</p></div>"+form(cadastro?"/criar-conta":"/entrar","auth-card")+mensagem+nome+input("E-mail","email","email",254)+"<label>Senha<input name='senha' type='password' autocomplete='"+(cadastro?"new-password":"current-password")+"' minlength='8' maxlength='256' required></label><button>"+(cadastro?"Criar conta":"Entrar")+"</button><p>"+alt+"</p></form></section>");}

    String perfil(DTO.Cliente cliente,List<DTO.Historico> historico,boolean ok,boolean limpo){
        String aviso=ok?"<div class='notice ok'>Seus dados foram atualizados.</div>":limpo?"<div class='notice ok'>O histórico de consultas foi limpo.</div>":"";
        var h=new StringBuilder("<div class='history-list'>");
        if(historico.isEmpty())h.append("<p>Você ainda não consultou nenhum imóvel.</p>");
        for(var item:historico)h.append("<a href='/imovel?id=").append(item.imovelId()).append("'><span><strong>").append(e(item.titulo())).append("</strong><small>").append(e(item.bairro())).append(" · ").append(data(item.consultadoEm())).append("</small></span><span>").append(dinheiro(item.preco())).append("</span></a>");
        h.append("</div>");
        String limpar=historico.isEmpty()?"":form("/perfil/historico/limpar","inline")+"<button class='secondary'>Limpar histórico</button></form>";
        return pagina("Meu perfil","<div class='page-title compact'><p class='eyebrow'>MINHA CONTA</p><h1>Olá, "+e(cliente.nome().split(" ")[0])+".</h1><p>Gerencie seus dados e retome os imóveis consultados.</p></div>"+aviso+"<div class='profile-grid'><section><h2>Dados pessoais</h2>"+form("/perfil","profile-form")+inputValor("Nome completo","nome","text",100,cliente.nome())+inputValor("E-mail","email","email",254,cliente.email(),true)+inputValor("Telefone","telefone","tel",25,cliente.telefone())+"<button>Salvar alterações</button></form></section><section><div class='section-line'><h2>Últimos imóveis consultados</h2>"+limpar+"</div>"+h+"</section></div>");
    }

    String agendar(DTO.Imovel i,List<DTO.Horario> horarios,List<List<Object>> clientes){String intro="<div class='booking-summary'><span class='mini-photo photo-"+((i.id()%4)+1)+"'></span><div><strong>"+e(i.titulo())+"</strong><small>"+e(i.bairro())+" · "+dinheiro(i.preco())+"</small></div></div>";if(horarios.isEmpty())return pagina("Agendar visita",intro+"<div class='notice'>Não há horários livres nos próximos 21 dias.</div>");var b=new StringBuilder(intro).append(form("/agendar","auth-card booking")).append(hidden("imovel",i.id()));if(staff)b.append(selecao("Cliente","cliente",clientes,null,true));b.append("<label>Horário com corretor<select name='horario' required><option value=''>Selecione</option>");for(var h:horarios)b.append(option(h.id(),h.inicio().format(DATA)+" · "+h.corretor(),null));b.append("</select></label><p>As visitas duram uma hora e seguem o horário de Brasília.</p><button>Confirmar agendamento</button></form>");return pagina("Agendar visita",b.toString());}

    String visitas(List<List<Object>> linhas,List<List<Object>> clientes,List<List<Object>> corretores,Long cliente,Long corretor,boolean ok){var b=new StringBuilder("<div class='page-title compact'><p class='eyebrow'>AGENDA</p><h1>").append(staff?"Visitas da equipe":"Minhas visitas").append("</h1></div>").append(ok(ok));if(staff)b.append("<form class='filters' action='/visitas'>").append(selecao("Cliente","cliente",clientes,cliente,false)).append(selecao("Corretor","corretor",corretores,corretor,false)).append("<button>Filtrar</button></form>");var registros=new ArrayList<List<String>>();for(var r:linhas){String acoes="—";if("PENDENTE".equals(r.get(5))){acoes=form("/visitas/status","inline")+hidden("id",r.get(0))+(staff?"<button name='status' value='REALIZADA'>Realizar</button>":"")+"<button class='secondary' name='status' value='CANCELADA'>Cancelar</button></form>";}registros.add(List.of(e(r.get(1)),e(r.get(2)),e(r.get(3)),data(r.get(4)),status(r.get(5)),dinheiro(r.get(6)),acoes));}return pagina("Visitas",b+grade(List.of("Cliente","Imóvel","Corretor","Horário","Status","Preço","Ações"),registros));}

    String gestao(String tipo,ImobiliariaDAO dao,boolean salvo)throws SQLException{String abas="<div class='tabs'><a href='/gestao/relatorios'>Relatórios</a><a href='/gestao/imoveis'>Imóveis</a><a href='/gestao/clientes'>Clientes</a><a href='/gestao/corretores'>Corretores</a><a href='/gestao/proprietarios'>Proprietários</a><a href='/gestao/horarios'>Horários</a></div>";String titulo,campos,dados;switch(tipo){case"imoveis"->{titulo="Imóveis";campos=input("Título","titulo","text",100)+"<label>Descrição<textarea name='descricao' maxlength='1200' required></textarea></label>"+selecaoSimples("Tipo","tipo",List.of("CASA","SOBRADO","APARTAMENTO","TERRENO"))+input("Bairro","bairro","text",70)+inputValor("Cidade","cidade","text",70,"Rio do Sul")+input("Endereço","endereco","text",180)+input("Quartos","quartos","number",3)+input("Banheiros","banheiros","number",3)+input("Vagas","vagas","number",3)+input("Área em m²","area","text",12)+input("Preço em R$","preco","text",15)+selecao("Proprietário","proprietario",dao.proprietarios(),null,true)+"<label class='check'><input type='checkbox' name='destaque'>Imóvel em destaque</label>";var ls=new ArrayList<List<String>>();for(var i:dao.imoveis(false)){String cx=form("/gestao/imovel/status","inline")+hidden("id",i.id())+"<select aria-label='Status' name='status'>";for(var s:DTO.StatusImovel.values())cx+=option(s,status(s),i.status());cx+="</select><button>Atualizar</button></form>";ls.add(List.of(e(i.titulo()),e(i.bairro()),dinheiro(i.preco()),cx));}dados=grade(List.of("Imóvel","Bairro","Preço","Status"),ls);}case"horarios"->{titulo="Horários dos corretores";campos=selecao("Corretor","corretor",dao.corretores(),null,true)+"<label>Hora cheia (Brasília)<input name='inicio' type='datetime-local' required step='3600'></label>";dados="<p>Novos horários ficam disponíveis para agendamento nos próximos 21 dias.</p>";}default->{titulo=switch(tipo){case"clientes"->"Clientes";case"corretores"->"Corretores";default->"Proprietários";};campos=input("Nome","nome","text",100)+input("E-mail","email","email",254);if(tipo.equals("corretores")){campos+=input("CRECI","creci","text",30);dados=tabela(List.of("ID","Nome","E-mail","CRECI"),dao.corretores());}else{campos+=inputValor("Telefone","telefone","tel",25,"");dados=tabela(List.of("ID","Nome","E-mail"),tipo.equals("clientes")?dao.clientes():dao.proprietarios());}}}return pagina(titulo,"<div class='page-title compact'><p class='eyebrow'>GESTÃO</p><h1>"+titulo+"</h1></div>"+abas+ok(salvo)+"<section><h2>Novo cadastro</h2>"+form("/gestao/"+tipo,"admin-form")+campos+"<button>Salvar no Supabase</button></form></section>"+dados);}

    String relatorios(DTO.Relatorios r){var b=new StringBuilder("<div class='page-title compact'><p class='eyebrow'>GESTÃO</p><h1>Relatórios de visitas</h1></div><div class='tabs'><a href='/gestao/relatorios'>Relatórios</a><a href='/gestao/imoveis'>Imóveis</a><a href='/gestao/clientes'>Clientes</a><a href='/gestao/corretores'>Corretores</a><a href='/gestao/proprietarios'>Proprietários</a><a href='/gestao/horarios'>Horários</a></div><div class='metric'><span>Ticket médio das visitas realizadas</span><strong>").append(dinheiro(r.ticketMedio())).append("</strong></div><div class='panels'><section><h2>Ranking de imóveis</h2>").append(tabela(List.of("Imóvel","Realizadas"),r.ranking())).append("</section><section><h2>Baixa procura</h2>").append(grade(List.of("Imóvel","Bairro","Última visita"),r.baixaProcura().stream().map(x->List.of(e(x.get(0)),e(x.get(1)),x.get(2)==null?"Nenhuma":data(x.get(2)))).toList())).append("</section></div><section><h2>Produtividade por corretor</h2>").append(tabela(List.of("Corretor","Realizadas","Pendentes","Canceladas"),r.produtividade())).append("</section><div class='panels'><section><h2>Visitas por bairro</h2>").append(barras(r.bairros(),View::e)).append("</section><section><h2>Status das visitas</h2>").append(barras(r.statusDasVisitas(),View::status)).append("</section><section><h2>Dias de pico</h2>").append(barras(r.picosPorDia(),v->List.of("Seg","Ter","Qua","Qui","Sex","Sáb","Dom").get(((Number)v).intValue()-1))).append("</section><section><h2>Horários de pico</h2>").append(barras(r.picosPorHora(),v->e(v)+"h")).append("</section></div>");return pagina("Relatórios",b.toString());}

    private static String barras(List<List<Object>> linhas,Function<Object,String> rotulo){if(linhas.isEmpty())return"<p>Sem dados para exibir.</p>";long max=linhas.stream().mapToLong(r->((Number)r.get(1)).longValue()).max().orElse(1);var b=new StringBuilder("<ul class='chart'>");for(var r:linhas){long n=((Number)r.get(1)).longValue();b.append("<li><span>").append(rotulo.apply(r.get(0))).append("</span><meter max='").append(max).append("' value='").append(n).append("'></meter><strong>").append(n).append("</strong></li>");}return b.append("</ul>").toString();}
    private static String tabela(List<String> cab,List<List<Object>> linhas){return grade(cab,linhas.stream().map(r->r.stream().map(View::e).toList()).toList());}
    private static String grade(List<String> cab,List<List<String>> linhas){if(linhas.isEmpty())return"<p>Nenhum registro encontrado.</p>";var b=new StringBuilder("<div class='table-wrap'><table><thead><tr>");for(String c:cab)b.append("<th>").append(e(c)).append("</th>");b.append("</tr></thead><tbody>");for(var r:linhas){b.append("<tr>");for(String c:r)b.append("<td>").append(c).append("</td>");b.append("</tr>");}return b.append("</tbody></table></div>").toString();}
    private String form(String rota){return form(rota,"");}private String form(String rota,String classe){return"<form method='post' action='"+rota+"' class='"+classe+"'>"+hidden("csrf",csrf);}private static String hidden(String nome,Object valor){return"<input type='hidden' name='"+nome+"' value='"+e(valor)+"'>";}
    private static String input(String rotulo,String nome,String tipo,int max){return"<label>"+rotulo+"<input name='"+nome+"' type='"+tipo+"' maxlength='"+max+"' required></label>";}private static String inputValor(String rotulo,String nome,String tipo,int max,Object valor){return inputValor(rotulo,nome,tipo,max,valor,false);}private static String inputValor(String rotulo,String nome,String tipo,int max,Object valor,boolean disabled){return"<label>"+rotulo+"<input name='"+nome+"' type='"+tipo+"' maxlength='"+max+"' value='"+e(valor==null?"":valor)+"' "+(disabled?"disabled":"")+"></label>";}
    private static String selecao(String rotulo,String nome,List<List<Object>> lista,Long atual,boolean req){var b=new StringBuilder("<label>").append(rotulo).append("<select name='").append(nome).append("'").append(req?" required":"").append("><option value=''>").append(req?"Selecione":"Todos").append("</option>");for(var r:lista)b.append(option(r.get(0),r.get(1),atual));return b.append("</select></label>").toString();}private static String selecaoSimples(String rotulo,String nome,List<String> lista){var b=new StringBuilder("<label>").append(rotulo).append("<select name='").append(nome).append("' required>");for(String x:lista)b.append(option(x,tipo(x),null));return b.append("</select></label>").toString();}private static String option(Object valor,Object rotulo,Object atual){return"<option value='"+e(valor)+"'"+(Objects.equals(valor,atual)?" selected":"")+">"+e(rotulo)+"</option>";}private static String ok(boolean sim){return sim?"<div class='notice ok'>Alteração salva no Supabase.</div>":"";}
}
